SELECT COUNT(*)
FROM ${table}
WHERE host_id = #{hostId}

  AND status = #{status}


  AND scheduled_at >= #{from}


  AND scheduled_at <= #{to}

SELECT meetings_id, host_id, title, status, invite_code,
       default_lang, scheduled_at, created_at, updated_at, ended_at
FROM ${table}
WHERE host_id = #{hostId}

  AND status = #{status}


  AND scheduled_at >= #{from}


  AND scheduled_at <= #{to}

ORDER BY scheduled_at DESC, meetings_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT meetings_id, host_id, title, status, invite_code,
       default_lang, scheduled_at, created_at, updated_at, ended_at
FROM ${table}
WHERE ${pk} = #{id}
  AND host_id = #{hostId}

SELECT meetings_id, host_id, title, status, invite_code,
       default_lang, scheduled_at, created_at, updated_at, ended_at
FROM ${table}
WHERE invite_code = #{inviteCode}
LIMIT 1

SELECT meetings_id, host_id, title, status, invite_code,
       default_lang, scheduled_at, created_at, updated_at, ended_at
FROM ${table}
WHERE host_id = #{hostId}
  AND title = #{title}
  AND status IN ('SCHEDULED','ONGOING')
  AND (updated_at >= #{since} OR scheduled_at >= #{since})
ORDER BY updated_at DESC, meetings_id DESC
LIMIT 1

