SET status = 'ONGOING'
WHERE ${pk} = #{id} AND host_id = #{hostId}

UPDATE ${table}
SET status = 'ENDED', ended_at = #{endedAt}
WHERE ${pk} = #{id} AND host_id = #{hostId}

