WHERE ${pk} = #{id} AND host_id = #{hostId}

mapper.select:
SELECT DISTINCT m.meetings_id, m.host_id, m.title, m.status, m.invite_code, m.default_lang, m.scheduled_at, m.ended_at, m.created_at, CASE WHEN m.host_id = #{userId} THEN 'HOST' ELSE COALESCE(p.role, 'GUEST') END AS user_role, -- 호스트 정보 host.name AS host_name, host.email AS host_email, host.profile_image_url AS host_profile_image_url, host.locale AS host_locale FROM tl_meetings m LEFT JOIN tl_meeting_participants p ON m.meetings_id = p.meetings_id AND p.user_id = #{userId} LEFT JOIN tl_users host ON m.host_id = host.user_id WHERE m.host_id = #{userId} OR p.user_id = #{userId}
AND m.status = #{status}
AND m.scheduled_at >= #{from}
AND m.scheduled_at <= #{to}
ORDER BY m.scheduled_at DESC, m.meetings_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT m.meetings_id)
FROM tl_meetings m
LEFT JOIN tl_meeting_participants p 
    ON m.meetings_id = p.meetings_id AND p.user_id = #{userId}
WHERE m.host_id = #{userId}
   OR p.user_id = #{userId}

    AND m.status = #{status}


    AND m.scheduled_at >= #{from}


    AND m.scheduled_at <= #{to}

