UPDATE tl_meetings
culture_desc = #{cultureDesc}, culture_thumb_rel_path = #{cultureThumbRelPath}, updated_at = CURRENT_TIMESTAMP
WHERE meetings_id = #{meetingId}

mapper.select:
SELECT COUNT(*)
FROM tl_meetings
WHERE meeting_mode = #{mode}

  AND status = #{status}


  AND host_id = #{hostId}

SELECT meetings_id, host_id, title, status, invite_code, default_lang, meeting_mode, scheduled_at, created_at, updated_at, ended_at, culture_desc AS cultureDesc, culture_thumb_rel_path AS cultureThumbRelPath FROM tl_meetings WHERE meeting_mode = #{mode}
AND status = #{status}
AND host_id = #{hostId}
ORDER BY COALESCE(updated_at, created_at) DESC, meetings_id DESC LIMIT #{limit} OFFSET #{offset}
